"use client";
import { useEffect, useRef, useState, createElement } from "react";
import Section from "./Section";
import { useLang } from "./LanguageProvider";
import { ui } from "@/data/content";

const MODEL = "/models/carro.glb";

export default function Car3D() {
  const { t } = useLang();
  const ref = useRef<any>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => { 
    import("@google/model-viewer"); 
  }, []);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // MÁGICA DA COR: Usando a API correta do model-viewer
    const onLoad = () => {
      if (el.model && el.model.materials) {
        el.model.materials.forEach((material: any) => {
          // Converte o Hex #001935 para RGB normalizado (0 a 1)
          // R: 0, G: 25/255 = 0.098, B: 53/255 = 0.207
          material.pbrMetallicRoughness.setBaseColorFactor([0, 0.098, 0.207, 1.0]);
          
          // Aplica o brilho metálico
          material.pbrMetallicRoughness.setMetallicFactor(0.8);
          material.pbrMetallicRoughness.setRoughnessFactor(0.2);
        });
      }
    };

    el.addEventListener("load", onLoad);
    
    const onError = () => setFailed(true);
    el.addEventListener("error", onError);

    return () => {
      el.removeEventListener("load", onLoad);
      el.removeEventListener("error", onError);
    };
  }, []);

  return (
    <Section id="car3d" title={t(ui.car3dTitle || { pt: "Conheça o Carro", en: "Meet the Car" })}>
      <div className="flex justify-between items-end mb-6">
        <p className="text-muted">
          {t(ui.car3dText || { pt: "Arraste para girar o carro em 360°.", en: "Drag to rotate the car 360°." })}
        </p>
        <button 
          onClick={() => { if (ref.current) ref.current.cameraOrbit = "0deg 75deg 105%"; }}
          className="text-xs text-cyan border border-cyan/30 px-3 py-1 rounded-full hover:bg-cyan/10 transition-colors"
        >
          Resetar Câmera
        </button>
      </div>

      <div className="w-full h-[55vh] rounded-3xl border border-cyan/30 bg-card/60 overflow-hidden relative">
        {failed ? (
          <div className="w-full h-full flex items-center justify-center text-muted text-sm">
            Erro ao carregar o carro 3D.
          </div>
        ) : (
          createElement("model-viewer", {
            ref: ref,
            src: MODEL,
            alt: "Carro da Vyperion Racing",
            "camera-controls": true,
            "disable-pan": true,
            "auto-rotate": true,
            "rotation-per-second": "15deg",
            "auto-rotate-delay": "1500", // Volta a girar 1.5s após soltar o dedo/mouse
            "interaction-prompt": "none",
            "touch-action": "pan-y",
            "shadow-intensity": "1.5",
            "environment-image": "neutral",
            exposure: "1.2",
            orientation: "0deg 90deg 90deg",
            "camera-orbit": "0deg 75deg 105%",
            style: { width: "100%", height: "100%", background: "transparent", outline: "none" }
          })
        )}
      </div>
    </Section>
  );
}