"use client";
import Img from "./Img";
// Logo quadrado, sempre do mesmo tamanho. Fundo claro para qualquer logo aparecer bem.
export default function LogoTile({ name, src, link, size }: { name: string; src?: string; link: string; size: string }) {
  return (
    <a href={link} aria-label={name} className={`${size} shrink-0 rounded-2xl bg-white flex items-center justify-center overflow-hidden`}>
      <Img src={src} alt={name} className="w-full h-full object-contain p-3" fallback={<span className="px-2 text-center text-xs font-bold text-navy/70">{name}</span>} />
    </a>);
}
