"use client";
import { motion } from "framer-motion";
import Section, { stagger, rise, vp } from "./Section";
import LogoTile from "./LogoTile";
import { useLang } from "./LanguageProvider";
import { partners, links, ui } from "@/data/content";
import { partnerLogos } from "@/data/images";
import { institutions } from "@/data/institutions";

// Ordem: instituições, depois platinum → bronze. Todos com o mesmo tamanho.
const order = ["platinum", "gold", "silver", "bronze"];
const list = [
  ...institutions,
  ...[...partners].sort((a, b) => order.indexOf(a.tier) - order.indexOf(b.tier)).map((p) => ({ name: p.name, src: partnerLogos[p.name], link: p.link })),
];
export default function PartnersSection() {
  const { t } = useLang();
  return (
    <Section id="partners" title={t(ui.partnersTitle)}>
      <motion.div variants={stagger} initial="hidden" whileInView="show" viewport={vp} className="flex flex-wrap justify-center gap-6 md:gap-8">
        {list.map((p) => (
          <motion.div key={p.name} variants={rise} whileTap={{ scale: 0.95 }}>
            <LogoTile name={p.name} src={p.src} link={p.link} size="w-40 h-40 md:w-48 md:h-48" />
          </motion.div>))}
      </motion.div>
      <div className="mt-12 text-center">
        <motion.a whileTap={{ scale: 0.95 }} href={`mailto:${links.email}?subject=Parceria Vyperion Racing`} className="btn inline-flex items-center px-10 rounded-full bg-cyan text-navy font-display font-bold">{t(ui.becomePartner)}</motion.a>
      </div>
    </Section>);
}
