"use client";
import { useState } from "react";
import { motion } from "framer-motion";
import Section, { stagger, rise, vp } from "./Section";
import { useLang } from "./LanguageProvider";
import Img from "./Img";
import { teamMembers, ui } from "@/data/content";
import { teamPhotos } from "@/data/images";
export default function TeamSection() {
  const { t } = useLang();
  const [shown, setShown] = useState<number | null>(null);
  return (
    <Section id="team" title="The Minds Behind Vyperion" subtitle={t(ui.teamSub)}>
      <p className="max-w-3xl text-muted leading-relaxed">{t(ui.teamText)}</p>
      <motion.div variants={stagger} initial="hidden" whileInView="show" viewport={vp} className="mt-10 grid grid-cols-2 lg:grid-cols-4 gap-5">
        {teamMembers.map((m, i) => (
          <motion.button key={m.name} variants={rise} whileTap={{ scale: 0.95 }} onClick={() => setShown(shown === i ? null : i)}
            className="p-5 rounded-2xl bg-card/80 border border-cyan/20 text-center min-h-[200px] flex flex-col items-center gap-2">
            <div className="w-20 h-20 rounded-full border-2 border-cyan overflow-hidden flex items-center justify-center font-display text-2xl text-cyan">
              <Img src={teamPhotos[m.name]} alt={m.name} className="w-full h-full object-cover" fallback={<span>{m.name[0]}</span>} />
            </div>
            <h3 className="font-display font-bold text-sm">{m.name}</h3>
            <p className="text-xs text-teal">{t(m.role)}</p>
            <p className={`text-xs text-muted transition-opacity duration-300 ${shown === i ? "opacity-100" : "opacity-0"}`}>{t(m.bio)}</p>
          </motion.button>))}
      </motion.div>
    </Section>);
}
